import { CAPABILITIES_LOT_3 } from '../completion/capabilitiesLot3.js';
import { area, beam, buff, cleanse, defend, guard, heal, hit, shot } from './rules.js';

// Three actions chosen explicitly for every roster ID. The old completion row
// supplies bibliography and universe identity only; it never selects an action.
// Ranges, timing, mitigation and resource values remain gameplay adaptations.
const kit = (id, simple, secondary, defense, sourceReference, identityBasis = 'canonical-role') => {
  const source = CAPABILITIES_LOT_3[id];
  if (!source) throw new Error('Unknown ability source in lot 3: ' + id);
  return {
    universe: source.universe, sourceWork: source.sourceWork, sourceReference,
    sourceUrl: source.sourceUrl || null, sourceRecord: 'CAPABILITIES_LOT_3/' + id,
    identityBasis, canonicalVerified: false, networkVerified: false, gameplayAdaptation: true,
    simple, secondary: { cd: 6, ...secondary }, defense
  };
};

