  ray_wotw: kit('ray_wotw', buff('Ray repère un abri pour les enfants'), guard('Faire passer sa famille à couvert'), defend('Se protéger avec Rachel et Robbie'), 'La Guerre des Mondes (2005) présente Ray comme un père civil qui tente de protéger ses enfants ; la protection ne devient pas un entraînement militaire.'),
  rachel_wotw: kit('rachel_wotw', buff('Rachel garde le contact avec sa famille'), cleanse('Reprendre son calme avec un proche'), defend('Rester à l’abri avec Rachel'), 'Rachel est une enfant civile dans La Guerre des Mondes ; les actions sont contact, réassurance et refuge, sans attaque ni pouvoir psychique.'),
  robbie_wotw: kit('robbie_wotw', buff('Robbie signale la route aux proches'), guard('Aider un proche à rejoindre l’abri'), defend('Repli de Robbie hors de la foule'), 'Robbie est un adolescent civil qui aide sa famille pendant l’invasion ; les gestes n’inventent ni arme ni qualification militaire.'),
  crysta_ferngully: kit('crysta_ferngully', buff('Crysta prépare la graine de la forêt'), heal('Croissance protectrice de Crysta'), defend('Abri des pousses de FernGully'), 'Crysta possède une magie féerique liée à la croissance et à la protection de la forêt ; le soin limité adapte ce rôle, sans certifier une guérison humaine identique au film.'),
  zak_ferngully: kit('zak_ferngully', buff('Zak repère la commande de la machine'), guard('Préparer l’arrêt de la machine forestière'), defend('Rejoindre le couvert de la forêt'), 'Zak est un humain qui aide à arrêter l’abattage dans FernGully ; ses actions sont pratiques et ne lui donnent pas la magie de Crysta.'),
